int   __wrap_EVP_Digest(const void* data, size_t count, unsigned char* md, unsigned int* size, const EVP_MD* type, ENGINE* impl);
int64_t __real_monotonic_nowMs(void);
int64_t __wrap_monotonic_nowMs(void);
