{
  static const char call_frame[] = R"({"jsonrpc":"2.0","id":"0123456789abcdef0123456789abcdef","method":"tools/call","params":{"name":"package_check_bulk","arguments":}})";
  TEST_ASSERT_TRUE(static_maxBodyByteCountOf("POST", 4, "/mcp", 4) >= (PACKAGECHECKBULK_JSON_OBJECT_BUF_SIZE - 1) + (sizeof(call_frame) - 1));
}

static bool static_isRawBodyPlaceNeededOf(const char* method, const char* target)
{
  ReceiveResult_t request;
  memset(&request, 0, sizeof(request));
  request.mp_method          = method;
  request.m_methodLen        = strlen(method);
  request.mp_requestTarget   = target;
  request.m_requestTargetLen = strlen(target);
  RequestHead_t head;
  request_readHead(&request, &head);
  return request_isRawBodyPlaceNeeded(&head);
}

void test_isRawBodyPlaceNeeded_only_for_a_method_the_raw_body_row_allows(void)
{
  TEST_ASSERT_TRUE(static_isRawBodyPlaceNeededOf("POST", "/image_inspect"));
  TEST_ASSERT_TRUE(static_isRawBodyPlaceNeededOf("POST", "/image_inspect?x=1"));

  static const struct {
    const char* mp_method;
    const char* mp_target;
  } others[] = {
    { "GET",      "/image_inspect" },
    { "HEAD",     "/image_inspect" },
    { "POSTPOST", "/image_inspect" },
    { "POST",     "/mcp" },
    { "POST",     "/cve_lookup_bulk" },
    { "POST",     "/driver_lookup_bulk" },
    { "POST",     "/no_such_path" },
  };
  for (size_t i = 0; i < sizeof(others) / sizeof(others[0]); i++)
    TEST_ASSERT_FALSE_MESSAGE(static_isRawBodyPlaceNeededOf(others[i].mp_method, others[i].mp_target), others[i].mp_target);
  TEST_ASSERT_FALSE(static_isRawBodyPlaceNeededOf("POST", "/package_check_bulk"));
}

void test_maxBodyByteCount_reads_a_target_of_1023_bytes(void)
{
  static char target[1025];
  memset(target, 'a', sizeof(target));
  memcpy(target, "/image_inspect?x=", 17);
  TEST_ASSERT_EQUAL_UINT(ENDPOINT_MAX_BODY_BYTE_COUNT, static_maxBodyByteCountOf("POST", 4, target, 1023));
  TEST_ASSERT_EQUAL_UINT(ROOM_AFTER_HEAD, static_maxBodyByteCountOf("POST", 4, target, 1024));
}

