void test_credit_cost_every_endpoint_row_has_a_pinned_price(void)
{
  for (int i = 0; i < endpoint_count; i++)
  {
    const RowPrice_t* row_price = NULL;
    for (size_t j = 0; j < sizeof(ROW_PRICES) / sizeof(ROW_PRICES[0]); j++)
    {
      if (strcmp(ROW_PRICES[j].mp_row, endpoints[i].mp_httpPath) == 0)
        row_price = &ROW_PRICES[j];
    }
    TEST_ASSERT_NOT_NULL_MESSAGE(row_price, endpoints[i].mp_httpPath);

    if (row_price->mp_request != NULL)
      TEST_ASSERT_EQUAL_UINT_MESSAGE(row_price->m_cost, static_costForPath(row_price->mp_request), row_price->mp_request);
  }
}

void test_credit_cost_flat_rows_ignore_ghsa(void)
{
  for (size_t j = 0; j < sizeof(ROW_PRICES) / sizeof(ROW_PRICES[0]); j++)
  {
    if (ROW_PRICES[j].mp_request == NULL || strcmp(ROW_PRICES[j].mp_row, "/cve_lookup/") == 0)
      continue;

    char path[256];
    int written = snprintf(path, sizeof(path), "%s?include_ghsa=true", ROW_PRICES[j].mp_request);
    TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < sizeof(path), ROW_PRICES[j].mp_request);
    TEST_ASSERT_EQUAL_UINT_MESSAGE(ROW_PRICES[j].m_cost, static_costForPath(path), path);
  }
}

