void test_CVELOOKUP_db_ok(void)
{
  g_stub_CVELOOKUP_status = DB_OK;

  const char* req =
    "GET /cve_lookup/CVE-2021-44228 HTTP/1.1\r\n"
    "Host: localhost\r\n\r\n";
  char buf[RESP_BUF];
  static_callRequestHandle(req, buf, sizeof(buf));
  TEST_ASSERT_NOT_NULL(strstr(buf, "HTTP/1.1 200"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("cve_id":"CVE-2021-44228")"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("severity":"CRITICAL")"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("cvss_v3":9.8)"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("published_time":"2021-12-10")"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("epss_score":0.97560)"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("epss_percentile":0.99700)"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("cwe_id":"CWE-917")"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("in_kev":true)"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("poc_count":3)"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("vendor_advisory_count":2)"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("epss_trend":[])"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("cve_tags":["unsupported-when-assigned"])"));
  TEST_ASSERT_NOT_NULL(strstr(buf, R"("description":)"));
}

