    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), cases[i].mp_restStatusLine);
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, cases[i].mp_restStatusLine), cases[i].mp_restStatusLine);
