void test_mcp_cve_lookup_price_and_enrichment_agree(void)
{
  static const struct { const char* mp_args; unsigned int m_cost; int m_ghsaCalls; } cases[] = {
    { R"(,"arguments":{"cve_id":"CVE-2021-44228","include_ghsa":true})",                 1, 1 },
    { R"(,"arguments":{"include_ghsa":true,"cve_id":"CVE-2021-44228"})",                 1, 1 },
    { R"(,"arguments":{"cve_id":"CVE-2021-44228","include_ghsa":false})",                1, 0 },
    { R"(,"arguments":{"cve_id":"CVE-2021-44228"})",                             1, 0 },
    { R"(,"arguments":{"cve_id":"CVE-2021-44228","shodan":true,"include_ghsa":true})",   1, 0 },
    { R"(,"arguments":{"cve_id":"CVE-2021-44228","x":{"include_ghsa":true}})",           1, 0 },
    { R"(,"arguments":{"cve_id":"CVE-2021-44228","include_ghsa":false,"include_ghsa":true})",    1, 0 },
    { R"(,"arguments":{"cve_id":"CVE-2021-44228","include_ghsa":"yes"})",                1, 0 },
    { R"(,"arguments":{"include_ghsa":true})",                                           1, 0 },
    { R"(,"arguments":{"cve_id":"not-a-cve","include_ghsa":true})",                      1, 0 },
    { R"(,"arguments":[{"shodan":true,"include_ghsa":true}])",                           1, 0 },
    { "",                                                                        1, 0 },
  };
  g_stub_CVELOOKUP_status = DB_OK;
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    char body[512];
    int  written = snprintf(body, sizeof(body), R"({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"cve_lookup"%s}})", cases[i].mp_args);
    TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(body));
    g_stub_CVELOOKUPGHSA_call_count = 0;
    TEST_ASSERT_EQUAL_UINT_MESSAGE(cases[i].m_cost, static_costForRequest("POST", "/mcp", body), body);
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_ghsaCalls, g_stub_CVELOOKUPGHSA_call_count, body);
  }
}

