static void static_mcpTextOf(const char* answer, char* decoded, size_t decoded_size, const char* label)
{
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(answer, R"("isError":false)"), label);

  JsonReadSpan_t root, result, content, item, text;
  size_t offset = 0;
  TEST_ASSERT_EQUAL_INT_MESSAGE(JSONREAD_OK, jsonread_root(answer, strlen(answer), &root), label);
  TEST_ASSERT_EQUAL_INT_MESSAGE(JSONREAD_OK, jsonread_objectKey(root, "result", &result), label);
  TEST_ASSERT_EQUAL_INT_MESSAGE(JSONREAD_OK, jsonread_objectKey(result, "content", &content), label);
  TEST_ASSERT_EQUAL_INT_MESSAGE(JSONREAD_OK, jsonread_arrayNextElement(content, &offset, &item), label);
  TEST_ASSERT_EQUAL_INT_MESSAGE(JSONREAD_OK, jsonread_objectKey(item, "text", &text), label);
  TEST_ASSERT_EQUAL_INT_MESSAGE(JSONREAD_OK, jsonread_spanToStrStatus(text, decoded, decoded_size), label);
}

static const char* static_mcpCallThroughRequestHandle(const char* headers, const char* tool, const char* arguments, const char* secret, char* buf, size_t len)
{
  char req[2048];
  int written = snprintf(req, sizeof(req), "POST /mcp HTTP/1.1\r\n%sContent-Type: application/json\r\n\r\n"
                         R"({"jsonrpc":"2.0","id":1,"method":"tools/call","params":{"name":"%s","arguments":%s}})",
                         headers, tool, arguments);
  TEST_ASSERT_TRUE_MESSAGE(written > 0 && (size_t)written < sizeof(req), tool);
  static_callRequestHandleWithSecret(req, secret, buf, len);
  TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), buf);
  const char* answer = strstr(buf, "\r\n\r\n");
  TEST_ASSERT_NOT_NULL_MESSAGE(answer, buf);
  return answer + 4;
}

static void static_privacyMcpText(const char* headers, char* buf, size_t len, char* decoded, size_t decoded_size)
{
  const char* answer = static_mcpCallThroughRequestHandle(headers, "privacy_my_data", "{}", "test_secret", buf, len);
  TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 200"), buf);
  static_mcpTextOf(answer, decoded, decoded_size, "privacy_my_data");
}

