void test_docs_bulk_body_ceiling_copies_match_the_server(void)
{
  static const struct {
    const char*              mp_path;
    const DocsBulkSection_t* mp_sections;
    const char*              mp_nextHeading;
  } files[] = {
    { DOCS_API_PATH, DOCS_API_BULK_SECTIONS, "\n## " },
    { DOCS_MCP_PATH, DOCS_MCP_BULK_SECTIONS, "\n### " },
  };
  for (size_t d = 0; d < sizeof(files) / sizeof(files[0]); d++)
  {
    char* text = static_readDocsFile(files[d].mp_path);
    int mib_counts[DOCS_BULK_SECTION_COUNT] = { 0 };
    for (const char* f = strstr(text, " MiB"); f; f = strstr(f + 1, " MiB"))
    {
      const char* digits = f;
      while (digits > text && digits[-1] >= '0' && digits[-1] <= '9')
        digits--;
      int s = static_docsBulkSectionIndexAt(text, f, files[d].mp_sections, files[d].mp_nextHeading);
      if (digits == f || s < 0)
        continue;
      const Endpoint_t* row = endpoint_findByHttpPath(files[d].mp_sections[s].mp_httpPath, NULL);
      TEST_ASSERT_NOT_NULL(row);
      TEST_ASSERT_EQUAL_UINT_MESSAGE(row->m_jsonCeiling / (1024u * 1024u), (unsigned)strtoul(digits, NULL, 10), files[d].mp_sections[s].mp_heading);
      mib_counts[s]++;
    }
    for (int s = 0; s < DOCS_BULK_SECTION_COUNT; s++)
      TEST_ASSERT_EQUAL_INT_MESSAGE(1, mib_counts[s], files[d].mp_sections[s].mp_heading);
    free(text);
  }
}


