static bool static_findTokenUnit(const char* text, const char** line_out)
{
  static const char* const phrases[] = { "tokens/h", "tokens / h", "tokens per ", "token per ", "token cost",
                                         "token budget", "token-budget", "token bucket", "token-bucket", "0 token", "1 token",
                                         "2 token", "3 token", "4 token", "5 token", "6 token", "7 token", "8 token",
                                         "9 token" };
  for (const char* line = text; line != NULL && *line != '\0'; )
  {
    const char* line_end = strchr(line, '\n');
    size_t line_len = line_end != NULL ? (size_t)(line_end - line) : strlen(line);
    char lower[8192];
    size_t lower_len = line_len < sizeof(lower) - 1 ? line_len : sizeof(lower) - 1;
    for (size_t k = 0; k < lower_len; k++)
      lower[k] = (char)tolower((unsigned char)line[k]);
    lower[lower_len] = '\0';
    for (size_t ph = 0; ph < sizeof(phrases) / sizeof(phrases[0]); ph++)
    {
      if (strstr(lower, phrases[ph]) != NULL)
      {
        *line_out = line;
        return true;
      }
    }
    line = line_end != NULL ? line_end + 1 : NULL;
  }
  return false;
}

void test_prose_names_credits_not_tokens(void)
{
  static const char* const pages[] = { "/", "/pricing", "/quickstart", "/mcp-setup", "/cve-api",
                                       "/package-vulnerability-api", "/domain-monitoring-api", "/ip-intelligence-api",
                                       "/security-monitoring-api", "/terms", "/privacy", "/vendor-keys", "/welcome", "/llms.txt" };
  for (size_t i = 0; i < sizeof(pages) / sizeof(pages[0]); i++)
  {
    char* text = static_pageText(pages[i]);
    const char* line = NULL;
    bool has_token_unit = static_findTokenUnit(text, &line);
    TEST_ASSERT_FALSE_MESSAGE(has_token_unit, has_token_unit ? line : pages[i]);
    free(text);
  }
  static const char* const docs[] = { DOCS_API_PATH, DOCS_MCP_PATH };
  for (size_t i = 0; i < sizeof(docs) / sizeof(docs[0]); i++)
  {
    char* text = static_readDocsFile(docs[i]);
    const char* line = NULL;
    bool has_token_unit = static_findTokenUnit(text, &line);
    TEST_ASSERT_FALSE_MESSAGE(has_token_unit, has_token_unit ? line : docs[i]);
    free(text);
  }
  int description_count = 0;
  for (int i = 0; i < endpoint_count; i++)
  {
    if (endpoints[i].mp_mcpToolName == NULL)
      continue;
    const char* line = NULL;
    bool has_token_unit = static_findTokenUnit(endpoints[i].mp_mcpToolDescription, &line);
    TEST_ASSERT_FALSE_MESSAGE(has_token_unit, endpoints[i].mp_mcpToolName);
    has_token_unit = static_findTokenUnit(endpoints[i].mp_mcpToolTitle, &line);
    TEST_ASSERT_FALSE_MESSAGE(has_token_unit, endpoints[i].mp_mcpToolName);
    description_count++;
    for (int j = 0; j < endpoints[i].m_paramCount; j++)
    {
      const char* arg_description = endpoints[i].mp_params[j].mp_mcpArgDescription;
      if (arg_description == NULL)
        continue;
      has_token_unit = static_findTokenUnit(arg_description, &line);
      TEST_ASSERT_FALSE_MESSAGE(has_token_unit, arg_description);
      description_count++;
    }
  }
  TEST_ASSERT_TRUE(description_count > 0);
}

static void static_githubSlug(const char* heading, size_t heading_len, char* slug_out, size_t slug_size)
{
  size_t slug_len = 0;
  for (size_t k = 0; k < heading_len && slug_len + 1 < slug_size; k++)
  {
    unsigned char c = (unsigned char)heading[k];
    if (isalnum(c) || c == '-' || c == '_')
      slug_out[slug_len++] = (char)tolower(c);
    else if (c == ' ')
      slug_out[slug_len++] = '-';
  }
  slug_out[slug_len] = '\0';
}

void test_capability_pages_pair_each_div_with_its_tool(void)
{
  char* docs = static_readDocsFile(DOCS_API_PATH);
  static const char* const capability_pages[] = {
    "/cve-api", "/package-vulnerability-api", "/domain-monitoring-api", "/ip-intelligence-api",
    "/security-monitoring-api",
  };
  static const char div_start[] = "<div class=\"endpoint\">";
  static const char method_start[] = "<span class=\"method ";
  static const char path_start[] = "<span class=\"endpoint-path\">";
  static const char tool_start[] = "MCP <code>";
  static const char fragment_start[] = "blob/main/docs/API_Documentation.md#";
  for (size_t i = 0; i < sizeof(capability_pages) / sizeof(capability_pages[0]); i++)
  {
    char* page = static_pageText(capability_pages[i]);
    int div_count = 0;
    for (char* div = strstr(page, div_start); div != NULL; div = strstr(div + 1, div_start))
    {
      div_count++;
      char* div_end = strstr(div, "</div>");
      TEST_ASSERT_NOT_NULL_MESSAGE(div_end, capability_pages[i]);
      *div_end = '\0';
      char* method = strstr(div, method_start);
      TEST_ASSERT_NOT_NULL_MESSAGE(method, capability_pages[i]);
      char* path = strstr(method, path_start);
      TEST_ASSERT_NOT_NULL_MESSAGE(path, capability_pages[i]);
      path += strlen(path_start);
      char* path_end = strstr(path, "</span>");
      TEST_ASSERT_NOT_NULL_MESSAGE(path_end, capability_pages[i]);
      char listed[DOCS_ROW_MAX];
      snprintf(listed, sizeof(listed), "%.*s", (int)(path_end - path), path);
      int row = static_listedRow(listed);

      char* tool = strstr(path_end, tool_start);
      TEST_ASSERT_NOT_NULL_MESSAGE(tool, listed);
      tool += strlen(tool_start);
      char* tool_end = strstr(tool, "</code>");
      TEST_ASSERT_NOT_NULL_MESSAGE(tool_end, listed);
      char tool_name[64];
      snprintf(tool_name, sizeof(tool_name), "%.*s", (int)(tool_end - tool), tool);
      TEST_ASSERT_NOT_NULL_MESSAGE(endpoints[row].mp_mcpToolName, listed);
      TEST_ASSERT_EQUAL_STRING_MESSAGE(endpoints[row].mp_mcpToolName, tool_name, listed);
      *div_end = '<';
    }
    TEST_ASSERT_TRUE_MESSAGE(div_count > 0, capability_pages[i]);

    int fragment_count = 0;
    for (char* fragment = strstr(page, fragment_start); fragment != NULL; fragment = strstr(fragment + 1, fragment_start))
    {
      fragment += strlen(fragment_start);
      char fragment_text[160];
      snprintf(fragment_text, sizeof(fragment_text), "%.*s", (int)strcspn(fragment, "\""), fragment);
      bool is_heading = false;
      for (char* heading = strstr(docs, "\n#"); heading != NULL && !is_heading; heading = strstr(heading + 1, "\n#"))
      {
        char* title = heading + 1;
        while (*title == '#')
          title++;
        while (*title == ' ')
          title++;
        char slug[256];
        static_githubSlug(title, strcspn(title, "\n"), slug, sizeof(slug));
        is_heading = strcmp(slug, fragment_text) == 0;
      }
      TEST_ASSERT_TRUE_MESSAGE(is_heading, fragment_text);
      fragment_count++;
    }
    TEST_ASSERT_TRUE_MESSAGE(fragment_count > 0, capability_pages[i]);
    free(page);
  }
  free(docs);
}

