extern "C" RdapStatus_t g_stub_RDAP_lookup_status;

void test_docs_dns_refusals_match_the_server(void)
{
  static const struct { const char* mp_path; int m_apiCount; int m_mcpCount; } cases[] = {
    { "/dns_lookup/printer.local",        10, 1 },
    { "/dns_lookup/",                     10, 0 },
    { "/dns_takeover_check/",                 10, 0 },
    { "/dns_lookup/example.com",          4, 2 },
    { "/dns_takeover_check/shop.example.com", 4, 2 },
    { "/email_auth_check/",                   10, 0 },
    { "/email_auth_check/example.com",        4, 2 },
    { "/email_auth_check/example.com?dkim_selector=a_b",    1, 1 },
    { "/email_auth_check/example.com?dkim_selector=google", 1, 1 },
    { "/ssl_check/printer.local",             10, 1 },
    { "/ssl_check/",                          10, 0 },
    { "/ssl_check/example.com",               4, 2 },
    { "/ssl_check/www.example.com",           2, 1 },
    { "/whois_lookup/printer.local",          10, 1 },
    { "/whois_lookup/",                       10, 0 },
    { "/whois_lookup/co.uk",                  3, 2 },
    { "/whois_lookup/example.com",            2, 1 },
    { "/wayback_lookup/printer.local",        10, 1 },
    { "/wayback_lookup/",                     10, 0 },
    { "/headers_check/printer.local",         10, 1 },
    { "/headers_check/",                      10, 0 },
    { "/headers_check/example.com?include_full_header_values=yes", 1, 0 },
    { "/well_known/printer.local",            10, 1 },
    { "/well_known/",                         10, 0 },
    { "/ssl_check/shop.example.com",          2, 1 },
    { "/ssl_check/mail.example.com",          2, 1 },
  };
  char* api_text = static_readDocsFile(DOCS_API_PATH);
  char* mcp_text = static_readDocsFile(DOCS_MCP_PATH);
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    g_stub_DNSLOOKUP_status     = i == 3 ? DNS_LOOKUP_NOT_FOUND : DNS_LOOKUP_OK;
    g_stub_DNSTAKEOVERCHECK_status = i == 4 ? DNS_LOOKUP_NOT_FOUND : DNS_LOOKUP_OK;
    g_stub_EMAILAUTHCHECK_status   = i == 6 ? DNS_LOOKUP_NOT_FOUND : i == 8 ? DNS_LOOKUP_INVALID_NAME : DNS_LOOKUP_OK;
    g_stub_TLSPROBE_status         = i == 11 || i >= 24 ? TLSPROBE_NAME_NOT_FOUND : i == 12 ? TLSPROBE_ADDRESS_NOT_GLOBALLY_REACHABLE : TLSPROBE_OK;
    g_stub_ASKQUESTIONS_status     = i == 11 ? DNS_ANSWER_NXDOMAIN : DNS_ANSWER_OK;
    g_stub_ASKQUESTIONS_record_count = i == 24 ? 1 : 0;
    g_stub_RDAP_lookup_status      = i == 16 ? RDAP_NOT_REGISTERED : RDAP_OK;
    char buf[RESP_BUF];
    static_restGet(cases[i].mp_path, buf, sizeof(buf));
    char message[256];
    static_errorMessageOf(buf, message, sizeof(message));
    char quoted[260];
    snprintf(quoted, sizeof(quoted), "\"%s\"", message);
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_apiCount, static_countOccurrences(api_text, quoted), quoted);
    TEST_ASSERT_EQUAL_INT_MESSAGE(cases[i].m_mcpCount, static_countOccurrences(mcp_text, quoted), quoted);
  }
  g_stub_DNSLOOKUP_status     = DNS_LOOKUP_OK;
  g_stub_DNSTAKEOVERCHECK_status = DNS_LOOKUP_OK;
  g_stub_EMAILAUTHCHECK_status   = DNS_LOOKUP_OK;
  g_stub_TLSPROBE_status         = TLSPROBE_OK;
  g_stub_RDAP_lookup_status      = RDAP_OK;
  free(api_text);
  free(mcp_text);
}

