void test_docs_watch_rows_name_the_sql_eol_events(void)
{
  static const struct { const char* mp_sqlWhen; const char* mp_rowEnd; } rows[] = {
    { "WHEN p_endpoint_name = 'product_exposure'", " |" },
    { "WHEN p_endpoint_name = 'package_check'",    " of the endoflife.date product the package maps to |" },
  };
  char* sql = static_readDocsFile("sql/fn_watchlist.sql");
  char* api_text = static_readDocsFile(DOCS_API_PATH);
  char* mcp_text = static_readDocsFile(DOCS_MCP_PATH);
  for (size_t r = 0; r < sizeof(rows) / sizeof(rows[0]); r++)
  {
    WatchEventList_t sql_list = {};
    static_readSqlEventArray(sql, rows[r].mp_sqlWhen, &sql_list);
    const char* eol_names[3] = { NULL, NULL, NULL };
    int eol_count = 0;
    for (int i = 0; i < sql_list.m_count; i++)
    {
      if (strncmp(sql_list.ma_names[i], "eol_", 4) != 0)
        continue;
      TEST_ASSERT_TRUE_MESSAGE(eol_count < 3, rows[r].mp_sqlWhen);
      eol_names[eol_count++] = sql_list.ma_names[i];
    }
    TEST_ASSERT_EQUAL_INT_MESSAGE(3, eol_count, rows[r].mp_sqlWhen);

    char phrase[256];
    snprintf(phrase, sizeof(phrase), "the three end-of-life types `%s`, `%s` and `%s`%s", eol_names[0], eol_names[1], eol_names[2], rows[r].mp_rowEnd);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countOccurrences(api_text, phrase), phrase);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countOccurrences(mcp_text, phrase), phrase);
  }
  free(sql);
  free(api_text);
  free(mcp_text);
}

