void test_docs_ssl_check_504_messages_match_the_server(void)
{
  static const struct {
    TlsProbeStatus_t         m_status;
    TlsProbeHandshakeError_t m_handshakeError;
  } cases[] = {
    { TLSPROBE_CONNECT_FAILED,   TLSPROBE_HANDSHAKE_ERROR_NONE },
    { TLSPROBE_TIMEOUT,          TLSPROBE_HANDSHAKE_ERROR_NONE },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_ANSWER_NOT_TLS },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_PEER_CLOSED },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_PROTOCOL_VERSION },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_HANDSHAKE_FAILURE },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_UNRECOGNIZED_NAME },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_CLIENT_CERTIFICATE_REQUIRED },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_OTHER_ALERT },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_NO_CERTIFICATE },
    { TLSPROBE_HANDSHAKE_FAILED, TLSPROBE_HANDSHAKE_ERROR_OTHER },
  };
  char* api_text = static_readDocsFile(DOCS_API_PATH);
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    g_stub_TLSPROBE_status          = cases[i].m_status;
    g_stub_TLSPROBE_handshake_error = cases[i].m_handshakeError;
    char buf[RESP_BUF];
    static_restGet("/ssl_check/shop.example.com", buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(buf, "HTTP/1.1 504 "), buf);
    char message[256];
    static_errorMessageOf(buf, message, sizeof(message));
    char row[sizeof(message) + 8];
    snprintf(row, sizeof(row), "| `%s` |", message);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countOccurrences(api_text, row), row);
  }
  g_stub_TLSPROBE_status          = TLSPROBE_OK;
  g_stub_TLSPROBE_handshake_error = TLSPROBE_HANDSHAKE_ERROR_NONE;
  free(api_text);
}

