  static_errorMessageOf(buf, message, sizeof(message));
  static_assertEveryMention(api_text, "unknown body parameter; the body takes only cve_ids", message, '"');

  char watchlist_message[ENDPOINT_MESSAGE_BUF_SIZE];
  TEST_ASSERT_EQUAL_INT(400, static_watchlistRestAnswer("/watchlist_edit", R"({"x":1})", true, watchlist_message, sizeof(watchlist_message)));
  static_assertEveryMention(api_text, "unknown body parameter; the body takes only action, endpoint", watchlist_message, '"');

  char vendor_key_edit_message[ENDPOINT_MESSAGE_BUF_SIZE];
  TEST_ASSERT_EQUAL_INT(400, static_watchlistRestAnswer("/vendor_key_edit", R"({"x":1})", true, vendor_key_edit_message, sizeof(vendor_key_edit_message)));
