#define WEBHOOK_BODY_SLOT_COUNT 4
#define WEBHOOK_BODY_BUF_SIZE   2048
static char g_webhookBodies[WEBHOOK_BODY_SLOT_COUNT][WEBHOOK_BODY_BUF_SIZE];

static const char* static_webhookBodyWith(int slot, const char* base, const char* old_text, const char* new_text)
{
  const char* at = strstr(base, old_text);
  TEST_ASSERT_NOT_NULL_MESSAGE(at, old_text);
  int written = snprintf(g_webhookBodies[slot], sizeof(g_webhookBodies[slot]), "%.*s%s%s", (int)(at - base), base, new_text, at + strlen(old_text));
  TEST_ASSERT_TRUE(written > 0 && (size_t)written < sizeof(g_webhookBodies[slot]));
  return g_webhookBodies[slot];
}

static void static_signWebhookBody(const char* body, size_t body_len, char hex_out[BYTES_SHA256_HEX_LEN + 1])
{
  unsigned char digest[EVP_MAX_MD_SIZE];
  unsigned int  digest_len = 0;
  TEST_ASSERT_NOT_NULL(HMAC(EVP_sha256(), WEBHOOK_TEST_SECRET, (int)strlen(WEBHOOK_TEST_SECRET), (const unsigned char*)body, body_len, digest, &digest_len));
  TEST_ASSERT_EQUAL_UINT(32, digest_len);
  for (unsigned int i = 0; i < digest_len; i++)
    snprintf(hex_out + 2 * i, 3, "%02x", digest[i]);
}

static void static_postWebhook(const char* header_lines, const char* body, char* buf, size_t len)
{
  static char head[512];
  int head_len = snprintf(head, sizeof(head), "POST /webhook_lemonsqueezy HTTP/1.1\r\n%s\r\n", header_lines);
  TEST_ASSERT_TRUE(head_len > 0 && (size_t)head_len < sizeof(head));
  BinaryRequestCall_t call = { head, body, strlen(body) };
  TEST_ASSERT_FALSE(static_collectResponse(static_writeBinaryRequestHandle, &call, buf, len));
  TEST_ASSERT_NULL_MESSAGE(strstr(buf, "X-RateLimit-"), buf);
}

static void static_postSignedWebhook(const char* body, char* buf, size_t len)
{
  char signature[BYTES_SHA256_HEX_LEN + 1];
  static_signWebhookBody(body, strlen(body), signature);
  char header_line[128];
  snprintf(header_line, sizeof(header_line), "X-Signature: %s\r\n", signature);
  static_postWebhook(header_line, body, buf, len);
}

