void test_watchlist_domain_item_add_waits_on_an_upstream_thread(void)
{
  g_stub_WATCHLISTEDIT_status = DB_OK;
  static_useEveryUpstreamThread();
  int question_count_before = g_stub_ASKQUESTIONS_call_count;

  static const char* const upstream_objects[] = {
    R"({"action":"add","endpoint":"dns_lookup","domain":"example.com"})",
    R"({"action":"add","endpoint":"ssl_check","domain":"example.com"})",
  };
  static char buf[RESP_BUF];
  char message[ENDPOINT_MESSAGE_BUF_SIZE];
  for (size_t i = 0; i < sizeof(upstream_objects) / sizeof(upstream_objects[0]); i++)
  {
    TEST_ASSERT_EQUAL_INT_MESSAGE(503, static_watchlistRestAnswer("/watchlist_edit", upstream_objects[i], true, message, sizeof(message)), upstream_objects[i]);
    g_stub_api_key_state = DB_API_KEY_ACTIVE;
    static_mcpCallThroughRequestHandle(PARITY_KEY_HEADER, "watchlist_edit", upstream_objects[i], NULL, buf, sizeof(buf));
    TEST_ASSERT_EQUAL_INT_MESSAGE(503, static_restStatusOf(buf), upstream_objects[i]);
  }
  TEST_ASSERT_EQUAL_INT(question_count_before, g_stub_ASKQUESTIONS_call_count);
  TEST_ASSERT_EQUAL_INT(0, g_stub_WATCHLISTEDIT_call_count);

  static const char* const local_objects[] = {
    R"({"action":"remove","endpoint":"dns_lookup","domain":"example.com"})",
    R"({"action":"add","endpoint":"cve_lookup","cve_id":"CVE-2021-44228"})",
  };
  int expected_call_count = 0;
  for (size_t i = 0; i < sizeof(local_objects) / sizeof(local_objects[0]); i++)
  {
    TEST_ASSERT_EQUAL_INT_MESSAGE(200, static_watchlistRestAnswer("/watchlist_edit", local_objects[i], true, message, sizeof(message)), local_objects[i]);
    TEST_ASSERT_EQUAL_INT_MESSAGE(++expected_call_count, g_stub_WATCHLISTEDIT_call_count, local_objects[i]);
    g_stub_api_key_state = DB_API_KEY_ACTIVE;
    const char* answer = static_mcpCallThroughRequestHandle(PARITY_KEY_HEADER, "watchlist_edit", local_objects[i], NULL, buf, sizeof(buf));
    TEST_ASSERT_NOT_NULL_MESSAGE(strstr(answer, R"("isError":false)"), answer);
    TEST_ASSERT_EQUAL_INT_MESSAGE(++expected_call_count, g_stub_WATCHLISTEDIT_call_count, local_objects[i]);
  }
  TEST_ASSERT_EQUAL_INT(question_count_before, g_stub_ASKQUESTIONS_call_count);
  TEST_ASSERT_FALSE(upstream_tryEnter());
}

