void test_mcp_x402_paid_call_whose_run_fails_is_released_and_not_settled(void)
{
  static const struct { DbStatus_t m_cveStatus; const char* mp_answer; const char* mp_attemptRule; const char* mp_sourceRule; } cases[] = {
    { DB_ERROR,     R"({"jsonrpc":"2.0","id":21,"error":{"code":-32603,"message":"Internal error: database query failed"}})", "x402_failed_attempt",  "x402_unserved_source" },
    { DB_NOT_FOUND, R"("isError":true)",                                                                                    "x402_refused_attempt", "x402_refused_source" },
  };
  for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); i++)
  {
    setUp();
    static_startX402();
    g_stub_CVELOOKUP_status = cases[i].m_cveStatus;
    char buf[RESP_BUF];
    static_callMcpX402("", X402_TEST_MCP_CVE_CALL(X402_TEST_MCP_PAID_META), buf, false);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, static_countResponses(buf), cases[i].mp_attemptRule);
    static_assertLine(buf, "HTTP/1.1 200 OK\r\n");
    static_assertLine(buf, cases[i].mp_answer);
    TEST_ASSERT_NULL_MESSAGE(strstr(buf, "x402/payment-response"), buf);
    TEST_ASSERT_NULL_MESSAGE(strstr(buf, "x402Version"), buf);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, g_stub_X402_FACILITATOR_verify_count, cases[i].mp_attemptRule);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, g_stub_X402_FACILITATOR_settle_count, cases[i].mp_attemptRule);
    TEST_ASSERT_EQUAL_INT_MESSAGE(0, g_stub_X402_LEDGER_mark_settled_count, cases[i].mp_attemptRule);
    TEST_ASSERT_EQUAL_INT_MESSAGE(1, g_stub_X402_LEDGER_release_count, cases[i].mp_attemptRule);
    TEST_ASSERT_EQUAL_INT_MESSAGE(9, g_stub_THROTTLE_call_count, cases[i].mp_attemptRule);
    TEST_ASSERT_EQUAL_STRING("x402_unserved_release", g_stub_THROTTLE_calls[6].ma_ruleName);
    TEST_ASSERT_EQUAL_STRING(cases[i].mp_attemptRule, g_stub_THROTTLE_calls[7].ma_ruleName);
    TEST_ASSERT_EQUAL_STRING(cases[i].mp_sourceRule, g_stub_THROTTLE_calls[8].ma_ruleName);
    static_assertNoBudgetCall();
    tearDown();
  }
}

