  TEST_ASSERT_EQUAL_INT(X402_REQUEST_OPEN_OK, x402_request_dbOpenPayment(FAKE_CONN, &source, 1, X402_TEST_IP_SECRET, X402_TEST_MESSAGE_HASH, &first).m_status);
  TEST_ASSERT_EQUAL_INT(X402_REQUEST_OPEN_OK, x402_request_dbOpenPayment(FAKE_CONN, &source, 1, X402_TEST_IP_SECRET, X402_TEST_MESSAGE_HASH, &second).m_status);
